import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function CurationSection() {
  const [activeTab, setActiveTab] = useState(0);

  const curationList = [
    {
      id: 1,
      title: "싱 어 게인",
      sub: "#필름소사이어티",
      desc: "“지금 당장, 노래 하나 써 봅시다”\n팝스타의 꿈은 접었지만 음악안에 놓지 못한 무명 축가 가수, 톢.\n한편 잘나갔지만 지금은 나락 직전의 팝스타, 대니.\n우연히 만난 두 사람, 그들이 완성한 단 하나의 노래.\n하지만 그 곡은 오직 대니의 이름으로만 세상에 알려지는데-",
      image: "/img/event/02.jpg",
      subMovies: [
        { id: 101, title: "청년 조롱기 :", image: "/img/event/01.jpg" },
        { id: 102, title: "아가미", image: "/img/event/03.png" },
        { id: 103, title: "퍼펙트 블루", image: "/img/event/01.jpg" },
        { id: 104, title: "민간 혐오자", image: "/img/event/02.jpg" }
      ]
    },
    {
      id: 2,
      title: "아비정전",
      sub: "#클래식",
      desc: "1960년 홍콩, 아비는 자유롭게 날아다니는 발없는 새처럼 한 곳에 정착하지 못한다.\n지나쳐간 연인 수리과 루루, 그리고 경감 수까지.\n지울 수 없는 사랑의 기억을 품은 청춘들의 몽환적이고 쓸쓸한 자화상.",
      image: "/img/event/03.png",
      subMovies: [
        { id: 201, title: "중경삼림", image: "/img/event/01.jpg" },
        { id: 202, title: "화양연화", image: "/img/event/02.jpg" },
        { id: 203, title: "타락천사", image: "/img/event/03.png" },
        { id: 204, title: "해피 투게더", image: "/img/event/01.jpg" }
      ]
    }
  ];

  const currentItem = curationList[activeTab];

  return (
    <section className="w-full bg-gradient-to-b from-[#3b2570] via-[#2a1a4a] to-[#0b090e] pt-12 pb-24 px-6 text-white relative">
      
      <div className="max-w-5xl mx-auto">
        
        {/* 상단 타이틀 */}
        <div className="flex justify-between items-center mb-8 border-b border-purple-400/30 pb-3">
          <h2 className="text-xl font-black tracking-tight text-white">큐레이션</h2>
          <span className="text-xs font-bold text-purple-200 cursor-pointer hover:text-white transition">큐레이션 더보기 +</span>
        </div>

        {/* 메인 콘텐츠 카드 */}
        <div className="flex flex-col lg:flex-row items-center gap-10">
          
          {/* 좌측 메인 포스터 */}
          <div className="w-72 md:w-80 h-[420px] rounded-2xl overflow-hidden shadow-2xl shrink-0 border border-white/20 bg-black">
            <img src={currentItem.image} alt={currentItem.title} className="w-full h-full object-cover" />
          </div>

          {/* 우측 상세 설명 및 서브 영화 목록 */}
          <div className="flex flex-col flex-1 space-y-6 text-left">
            <div>
              <span className="text-xs font-bold text-purple-300 tracking-wider uppercase">{currentItem.sub}</span>
              <h3 className="text-3xl md:text-4xl font-black text-white mt-1 mb-3">{currentItem.title}</h3>
              <p className="text-xs text-purple-100/90 font-medium leading-relaxed whitespace-pre-line bg-white/5 p-4 rounded-xl border border-white/10">
                {currentItem.desc}
              </p>
            </div>

            {/* 서브 영화 목록 (가로 스크롤 / 그리드) */}
            <div className="grid grid-cols-4 gap-3 pt-2">
              {currentItem.subMovies.map((movie, idx) => (
                <div 
                  key={movie.id} 
                  onClick={() => setActiveTab(idx % curationList.length)}
                  className="cursor-pointer group flex flex-col gap-1.5"
                >
                  <div className="w-full h-28 rounded-lg overflow-hidden border border-white/20 shadow-md group-hover:scale-105 transition">
                    <img src={movie.image} alt={movie.title} className="w-full h-full object-cover" />
                  </div>
                  <span className="text-[11px] font-bold text-purple-200 truncate group-hover:text-white">{movie.title}</span>
                </div>
              ))}
            </div>

            {/* 상세정보 및 예매하기 버튼 */}
            <div className="flex gap-4 pt-2">
              <Link to="/movies" className="flex-1 text-center py-3.5 bg-white/10 hover:bg-white/20 text-white font-bold text-xs rounded-xl transition border border-white/20">
                상세정보
              </Link>
              <Link to="/schedule" className="flex-1 text-center py-3.5 bg-[#623ce4] hover:bg-[#502bb5] text-white font-bold text-xs rounded-xl transition shadow-lg">
                예매하기
              </Link>
            </div>

          </div>

        </div>

      </div>
    </section>
  );
}

export default CurationSection;
